KG42.register("rules-77b5ae922d6a654c43ff74f0",{"id":"38-bidirectional_ev_trading::v141-c-R011","paper":"38-bidirectional_ev_trading","record":{"rule_id":"v141-c-R011","mechanism_id":"M03","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"Robust collaborative scheduling maximizes the minimum actual social welfare over admissible load variations, subject to each customer's feasible scheduling set. Actual social welfare is total utility from actual appliance consumption minus the aggregator's cost of actual aggregate energy consumption. Scope: Robust collaborative scheduling for all customers and time-slots under load uncertainty. Condition: Load variations belong to the bounded uncertainty set.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.social_welfare"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Robust collaborative scheduling for all customers and time-slots under load uncertainty.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]},"x":[{"variable_id":"v141-c-R011-X01","symbol":"x_{i,App}^t","meaning":"Scheduled energy consumption of customer i's residential appliances, excluding the EV, at time-slot t; actual appliance consumption is x_{i,App}^t+e_i^t.","kind":"design_selection","domain":"Component of the customer schedule \\bar{x}_i in X_i, where X_i is customer i's feasible energy-scheduling set; this rule's evidence does not expand X_i.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]},{"variable_id":"v141-c-R011-X02","symbol":"x_{i,Tot}^t","meaning":"Scheduled total energy consumption of customer i at time-slot t, including residential appliances and the EV; actual total consumption is x_{i,Tot}^t+e_i^t.","kind":"design_selection","domain":"Component of the customer schedule \\bar{x}_i in X_i, where X_i is customer i's feasible energy-scheduling set; this rule's evidence does not expand X_i.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]},{"variable_id":"v141-c-R011-X03","symbol":"e_i^t","meaning":"Uncertain load variation for customer i at time-slot t; in RP it is chosen adversarially by the inner minimization over the bounded uncertainty set E.","kind":"operational","domain":"e_i^{min,t} \u003c= e_i^t \u003c= e_i^{max,t} for all i in I and t in T; equivalently \\bar{e} in \\mathcal{E}.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]}],"theta":[{"parameter_id":"v141-c-R011-T01","symbol":"U_i^t","meaning":"Given utility function for customer i's residential-appliance consumption at time-slot t, used in actual social welfare.","value":{"kind":"symbolic","number_value":null,"text_value":"given function U_i^t(\\cdot)"},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g02-e16"]},{"parameter_id":"v141-c-R011-T02","symbol":"C^t","meaning":"Given aggregator total-cost function at time-slot t, evaluated at actual aggregate energy consumption.","value":{"kind":"symbolic","number_value":null,"text_value":"given total cost function C^t(\\cdot)"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e16"]},{"parameter_id":"v141-c-R011-T03","symbol":"e_i^{min,t}","meaning":"Minimum admissible load variation for customer i at time-slot t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e15"]},{"parameter_id":"v141-c-R011-T04","symbol":"e_i^{max,t}","meaning":"Maximum admissible load variation for customer i at time-slot t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g02-e15"]},{"parameter_id":"v141-c-R011-T05","symbol":"X_i","meaning":"Feasible energy-scheduling set for customer i, appearing in the robust problem's constraint \\bar{x}_i in X_i.","value":{"kind":"symbolic","number_value":null,"text_value":"set X_i referenced by \\bar{x}_i\\in X_i"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-e16"]}],"phi":[{"constraint_id":"v141-c-R011-C001","kind":"procedural","role":"core","statement":"Robust collaborative scheduling maximizes the minimum actual social welfare over admissible load variations, subject to each customer's feasible scheduling set. Actual social welfare is total utility from actual appliance consumption minus the aggregator's cost of actual aggregate energy consumption. Scope: Robust collaborative scheduling for all customers and time-slots under load uncertainty. Condition: Load variations belong to the bounded uncertainty set.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]},{"constraint_id":"v141-c-R011-C002","kind":"mathematical","role":"core","statement":"Actual social welfare of the power system from actual energy consumptions is the sum over all customers and time-slots of utility from actual appliance consumption minus the aggregator's cost of actual aggregate energy consumption.","expression":"\\phi(\\bar{x},\\bar{e}) = \\sum_{t\\in T}\\sum_{i\\in I} U_i^t(x_{i,App}^t+e_i^t) - \\sum_{t\\in T} C^t\\left(\\sum_{i\\in I}(x_{i,Tot}^t+e_i^t)\\right)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R011-X01","v141-c-R011-X02","v141-c-R011-X03"],"parameter_refs":["v141-c-R011-T01","v141-c-R011-T02"],"evidence_ids":["v141-b-g02-e16"]},{"constraint_id":"v141-c-R011-C003","kind":"mathematical","role":"supporting","statement":"The uncertain load variation is bounded in the uncertainty set E with per-customer per-time lower and upper bounds.","expression":"\\mathcal{E} = \\{\\bar{e} \\mid e_i^{min,t} \\le e_i^t \\le e_i^{max,t}, \\ \\forall i\\in I, t\\in T\\}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R011-X03"],"parameter_refs":["v141-c-R011-T03","v141-c-R011-T04"],"evidence_ids":["v141-b-g02-e15"]},{"constraint_id":"v141-c-R011-C004","kind":"mathematical","role":"core","statement":"Robust collaborative clearing solves RP: maximize over customer schedules the minimum actual social welfare over the uncertainty set E, subject to each customer's schedule lying in X_i.","expression":"\\mathrm{RP}: \\max_{\\bar{x}} \\min_{\\bar{e}\\in\\mathcal{E}} \\phi(\\bar{x},\\bar{e}) \\quad \\text{s.t. } \\bar{x}_i\\in X_i, \\ \\forall i\\in I","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R011-X01","v141-c-R011-X02","v141-c-R011-X03"],"parameter_refs":["v141-c-R011-T01","v141-c-R011-T02","v141-c-R011-T03","v141-c-R011-T04","v141-c-R011-T05"],"evidence_ids":["v141-b-g02-e15","v141-b-g02-e16"]}],"pi":[{"evidence_id":"v141-b-g02-e15","location":{"location_id":"src-54c42059a7-p06-c2r2__v141-a-M03-clearing","page":6,"printed_page":"1224","section":"V. Uncertainty in Load Demands","anchor_text":"EV as xi,App + ei. For simplicity, we assume that when the load variation occur, each customer chang","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"We define the uncertain load variation in customer i's energy consumption for its residential appliances at time-slot t as e_i^t. Then, we can represent customer i's actual energy consumption for its residential appliances not including the EV as x_{i,App}^t + e_i^t. For simplicity, we assume that when the load variation occur, each customer change the total energy consumption by the same amount of energy as the load variation so that the total energy consumption of customer i at time-slot t is represented as x_{i,Tot}^t + e_i^t. We assume that the uncertain load variation is bounded in the following uncertainty set: \\mathcal{E} = \\{\\bar{e} \\mid e_i^{min,t} \\le e_i^t \\le e_i^{max,t}, \\ \\forall i\\in I, t\\in T\\}, \\quad (18) where e_i^{min,t} and e_i^{max,t} denote the minimum and maximum values of load variation e_i^t, respectively. The maximum and minimum values of each customer's load variation are approved by or at least known to the aggregator (e.g., through the history database)."},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-54c42059a7-p06-c2r3__v141-a-M03-clearing","page":6,"printed_page":"1224","section":"V. Uncertainty in Load Demands","anchor_text":"6), A. Load Demand Uncertainty in the Collaborative System t). he In the collaborative system, we ai","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"In the collaborative system, we aim to maximize the worst-case performance which is defined as the minimum social welfare of the power system under all possible load variation \\bar{e}\\in\\mathcal{E} using robust optimization techniques [25]. We first define the actual social welfare of the power system which comes from the actual energy consumptions as \\phi(\\bar{x},\\bar{e}) = \\sum_{t\\in T}\\sum_{i\\in I} U_i^t(x_{i,App}^t+e_i^t) - \\sum_{t\\in T} C^t\\left(\\sum_{i\\in I}(x_{i,Tot}^t+e_i^t)\\right). \\quad (19) Then, we formulate a robust optimization problem as RP: \\max_{\\bar{x}} \\min_{\\bar{e}\\in\\mathcal{E}} \\phi(\\bar{x},\\bar{e}) \\quad \\text{s.t. } \\bar{x}_i\\in X_i, \\ \\forall i\\in I."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M03-clearing","v141-a-M04-clearing"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e15","quote":"We assume that the uncertain load variation is bounded in the following uncertainty set:"},{"evidence_id":"v141-b-g02-e16","quote":"In the collaborative system, we aim to maximize the worst-case performance which is defined as the minimum social welfare of the power system under all possible load variation \\bar{e}\\in\\mathcal{E} using robust optimization techniques [25]. We first define the actual social welfare of the power system which comes from the actual energy consumptions as \\phi(\\bar{x},\\bar{e}) = \\sum_{t\\in T}\\sum_{i\\in I} U_i^t(x_{i,App}^t+e_i^t) - \\sum_{t\\in T} C^t\\left(\\sum_{i\\in I}(x_{i,Tot}^t+e_i^t)\\right). \\quad (19) Then, we formulate a robust optimization problem as RP: \\max_{\\bar{x}} \\min_{\\bar{e}\\in\\mathcal{E}} \\phi(\\bar{x},\\bar{e}) \\quad \\text{s.t. } \\bar{x}_i\\in X_i, \\ \\forall i\\in I."}]],"C2_formalization":{"graph_sha256":"7b511f28c524bdfea865e4a1ba70287960ef7a6024340e10d066022165836a42","applicability":"formalized","reason":"Formalized from the supplied B source texts: v141-b-g02-e15 gives the bounded uncertainty set (18), and v141-b-g02-e16 gives actual social welfare (19) and robust problem RP. The original C.1 procedural C001 is retained unchanged; new mathematical constraints record the source equations. B evidence is unreviewed in this experiment and is not claimed to have passed source audit.","bindings":[{"object_id":"v141-c-R011-X01","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"x_{i,App}^t is a decision component of the social-welfare clearing problem and appears in the actual welfare function φ and in the feasible schedule \\bar{x}_i in X_i."},{"object_id":"v141-c-R011-X02","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"x_{i,Tot}^t is a decision component of the social-welfare clearing problem and appears in the actual welfare function φ and in the feasible schedule \\bar{x}_i in X_i."},{"object_id":"v141-c-R011-X03","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"e_i^t is the uncertain load variation that the robust clearing objective minimizes over E; it enters φ through actual appliance and total consumption."},{"object_id":"v141-c-R011-T01","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"U_i^t is the given utility term in the actual social welfare definition for clearing.social_welfare."},{"object_id":"v141-c-R011-T02","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C^t is the given aggregator cost term in the actual social welfare definition for clearing.social_welfare."},{"object_id":"v141-c-R011-T03","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"e_i^{min,t} is a lower bound defining the uncertainty set E used in the robust social-welfare objective."},{"object_id":"v141-c-R011-T04","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"e_i^{max,t} is an upper bound defining the uncertainty set E used in the robust social-welfare objective."},{"object_id":"v141-c-R011-T05","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"X_i is the feasible scheduling set restricting the clearing decision \\bar{x}_i in the robust problem RP."},{"object_id":"v141-c-R011-C001","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Original C.1 procedural statement of the robust social-welfare clearing rule; retained unchanged."},{"object_id":"v141-c-R011-C002","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Formal source transcription of the actual social welfare φ that defines the clearing objective."},{"object_id":"v141-c-R011-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Formal source transcription of the bounded uncertainty set E used by the robust clearing objective; no separate graph node exists, so it binds to clearing.social_welfare as a supporting condition."},{"object_id":"v141-c-R011-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Formal source transcription of robust problem RP for clearing.social_welfare."}],"revision_requests":[]}},"quarantined_references":[]}});
